abel{display:block;font-size:8.5px;font-weight:800;color:#7b899b}.detail-value{display:block;margin-top:2px;font-size:10px;font-weight:800;color:#2b3e59;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:260px}.customer-change{display:flex;justify-content:flex-start;padding-top:12px}.customer-change .btn:disabled{opacity:.42;cursor:not-allowed}.customer-change .btn{height:36px;font-size:10px}.customer-skeleton{display:inline-block;width:78px;height:8px;border-radius:99px;background:#dfe7f0;vertical-align:middle}.customer-summary.is-ok .customer-skeleton,.customer-summary.is-bad .customer-skeleton{display:none}@media(max-width:850px){.service-line,.grid,.visit,.uploads{grid-template-columns:1fr 1fr}.span4{grid-column:1/-1}.asset-methods{grid-template-columns:1fr 1fr}.asset-card.show{grid-template-columns:1fr 1fr}.customer-details{grid-template-columns:1fr 1fr}.customer-summary-head{align-items:flex-start}.customer-name{max-width:240px}}@media(max-width:560px){.service-line,.grid,.visit,.uploads{grid-template-columns:1fr}.span2,.span4{grid-column:auto}.lookup-row,.asset-search.show{grid-template-columns:1fr}.asset-methods{grid-template-columns:1fr 1fr}.panel{padding:13px}.page-head h1{font-size:24px}.customer-summary-head{display:grid}.customer-details{grid-template-columns:1fr}.customer-detail:nth-child(4){border-bottom:1px solid #e3eaf2}.customer-name{max-width:210px}}
