mer-detail"><span class="detail-icon">▤</span><div><span class="detail-label">العنوان المختصر</span><span class="detail-value" id="summary-address"><span class="customer-skeleton"></span></span></div></div></div><div class="customer-change"><button type="button" class="btn ghost" id="change-customer" disabled>↻ تغيير العميل</button></div></div><input type="hidden" name="company_name" id="company_name"><input type="hidden" name="responsible_person" id="responsible_person"><input type="hidden" name="mobile" id="mobile"><input type="hidden" name="email" id="email"><input type="hidden" id="customer_city"><input type="hidden" id="customer_address"></section>
