<script>
(()=>{const $=id=>document.getElementById(id), apiCustomer='{{ route('public.request-service.customer') }}', apiAssets='{{ route('public.request-service.assets') }}';let customer=null,sites=[],contracts=[],assets=[];const status=$('customer-status'),summary=$('customer-summary'),statusSub=$('customer-status-sub'),stateIcon=$('customer-state-icon');
const serviceType=$('service-type'),sub=$('service-subtype'),future=$('future-box'),routine=$('routine-form');function serviceChoices(){const v=serviceType.value;sub.innerHTML=v==='maintenance'?'<option value="routine">صيانة عادية</option><option value="urgent">صيانة طارئة</option>':v==='quotation'?'<option value="parts">عرض سعر قطع غيار</option><option value="contract">عرض سعر عقد صيانة</option><option value="visit">عرض سعر زيارة فنية</option>':'<option value="technical">استشارة فنية</option>';toggleRoutine()}function toggleRoutine(){const ok=serviceType.value==='maintenance'&&sub.value==='routine';routine.classList.toggle('hidden',!ok);future.style.display=ok?'none':'block'}serviceType.addEventListener('change',serviceChoices);sub.addEventListener('change',toggleRoutine);
$('priority').addEventListener('change',e=>document.querySelector('input[name="urgency"]').value=e.target.value);
function valueOrDash(v){return v&&String(v).trim()?String(v):'—'}function setSummaryState(kind,title,subText){summary.classList.remove('is-ok','is-bad');if(kind==='ok')summary.classList.add('is-ok');if(kind==='bad')summary.classList.add('is-bad');status.textContent=title;statusSub.textContent=subText;stateIcon.textContent=kind==='ok'?'✓':kind==='bad'?'!':'i'}function renderSummary(c,no){$('summary-company').textContent=valueOrDash(c?.name);$('summary-code').textContent=valueOrDash(no);$('summary-contact').textContent=valueOrDash(c?.contact_name||c?.name);$('summary-mobile').textContent=valueOrDash(c?.phone);$('summary-email').textContent=valueOrDash(c?.email);$('summary-city').textContent=valueOrDash(c?.city);$('summary-address').textContent=valueOrDash(c?.address)}function resetCustomerSummary(clearNumber=false){customer=null;sites=[];contracts=[];assets=[];if(clearNumber)$('customer_number').value='';['company_name','responsible_person','mobile','email','customer_city','customer_address'].forEach(id=>$(id).value='');renderSummary(null,'');$('summary-company').innerHTML='<span class="customer-skeleton"></span>';$('summary-contact').innerHTML='<span class="customer-skeleton"></span>';$('summary-mobile').innerHTML='<span class="customer-skeleton"></span>';$('summary-email').innerHTML='<span class="customer-skeleton"></span>';$('summary-city').innerHTML='<span class="customer-skeleton"></span>';$('summary-address').innerHTML='<span class="customer-skeleton"></span>';setSummaryState('wait','بانتظار إدخال رقم العميل','أدخل رقم العميل ثم اضغط «جلب البيانات» لعرض معلوماته هنا.');$('change-customer').disabled=true;['contract-section','site-section','asset-section'].forEach(id=>$(id).classList.add('disabled-section'))}
$('customer-lookup').addEventListener('click',async()=>{const no=$('customer_number').value.trim();if(!no){setSummaryState('bad','أدخل رقم العميل أولًا','لم يتم إدخال رقم عميل للتحقق منه.');return}setSummaryState('wait','جارٍ جلب بيانات العميل…','يتم الآن التحقق من رقم العميل وتحميل بياناته.');try{const r=await fetch(apiCustomer+'?customer_number='+encodeURIComponent(no),{headers:{Accept:'application/json'}}),d=await r.json();if(!r.ok)throw new Error(d.message||'تعذر جلب البيانات');customer=d.customer;sites=d.sites||[];contracts=d.contracts||[];$('company_name').value=customer.name||'';$('responsible_person').value=customer.contact_name||customer.name||'';$('mobile').value=customer.phone||'';$('email').value=customer.email||'';$('customer_city').value=customer.city||'';$('customer_address').value=customer.address||'';renderSummary(customer,no);fillContracts();fillSites();['contract-section','site-section','asset-section'].forEach(id=>$(id).classList.remove('disabled-section'));setSummaryState('ok','تم التحقق من العميل','تم جلب بيانات العميل بنجاح.');$('change-customer').disabled=false}catch(e){customer=null;renderSummary(null,no);setSummaryState('bad','لم يتم العثور على العميل',e.message);$('change-customer').disabled=true;['contract-section','site-section','asset-section'].forEach(id=>$(id).classList.add('disabled-section'))}});$('change-customer').addEventListener('click',()=>{resetCustomerSummary(true);$('customer_number').focus()});
function fillContracts(){const el=$('contract_no');el.innerHTML='<option value="">اختر عقد العميل</option>'+contracts.map(c=>`<option value="${esc(c.contract_no||'')}" data-id="${c.id}">${esc(c.contract_no||'بدون رقم')} — ${esc(c.title||'عقد خدمة')}</option>`).join('')}function fillSites(){const el=$('site_id');el.innerHTML='<option value="">اختر الموقع</option>'+sites.map(s=>`<option value="${s.id}">${esc(s.name||s.site_code||'موقع')} — ${esc(s.city||'')}</option>`).join('')}
$('contract_no').addEventListener('change',async e=>{const c=contracts.find(x=>(x.contract_no||'')===e.target.value);$('contract_title').value=c?.title||'';$('contract_status').value=c?.status||'';await loadAssets()});$('site_id').addEventListener('change',async e=>{const s=sites.find(x=>String(x.id)===e.target.value);$('site_name').value=s?.name||'';$('site_city').value=s?.city||'';$('site_area').value=s?.city||'General';$('visible_site_address').value=s?.address||'';$('site_address').value=s?.address||'';$('site_contact').value=s?.contact_name||'';$('site_mobile').value=s?.contact_mobile||'';$('latitude').value=s?.latitude||'';$('longitude').value=s?.longitude||'';setMap(s);await loadAssets()});
function setMap(s){const f=$('map').querySelector('iframe');if(!s?.latitude||!s?.longitude){f.src='about:blank';return}const lat=Number(s.latitude),lon=Number(s.longitude),d=.025;f.src=`https://www.openstreetmap.org/export/embed.html?bbox=${lon-d}%2C${lat-d}%2C${lon+d}%2C${lat+d}&layer=mapnik&marker=${lat}%2C${lon}`}
async function loadAssets(key=''){if(!customer)return;const p=new URLSearchParams({customer_id:customer.id});if($('contract_no').value)p.set('contract_no',$('contract_no').value);if($('site_id').value)p.set('site_id',$('site_id').value);if(key)p.set('key',key);const r=await fetch(apiAssets+'?'+p.toString(),{headers:{Accept:'application/json'}}),d=await r.json();assets=d.assets||[];if(!key){$('asset-list').innerHTML='<option value="">اختر المعدة</option>'+assets.map(a=>`<option value="${a.id}">${esc(a.asset_code||'')} — ${esc(a.name||a.asset_type||'معدة')}</option>`).join('')}return assets}
$('asset-list').addEventListener('change',e=>selectAsset(assets.find(a=>String(a.id)===e.target.value)));$('asset-find').addEventListener('click',async()=>{const found=await loadAssets($('asset-key').value.trim());if(found.length)selectAsset(found[0]);else{alert('لم يتم العثور على معدة مطابقة لهذا العميل والعقد/الموقع المحدد.')}});
document.querySelectorAll('.asset-method').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('.asset-method').forEach(x=>x.classList.remove('active'));b.classList.add('active');const m=b.dataset.method;$('asset-list-wrap').style.display=m==='list'?'block':'none';$('asset-search').classList.toggle('show',['qr','asset','serial'].includes(m));$('manual-fields').classList.toggle('show',m==='manual');$('asset-card').classList.toggle('show',false);if(m==='manual'){$('asset_id').value='';$('asset_type').value=$('manual_type').value||'GENERAL'}$('asset-key').placeholder=m==='qr'?'امسح QR أو ألصق محتواه':m==='serial'?'أدخل السيريال نمبر':'أدخل رقم الأصل'}));
['manual_name','manual_type','manual_brand','manual_model'].forEach(id=>$(id).addEventListener('input',()=>{$('asset_type').value=$('manual_type').value||$('manual_name').value||'GENERAL';$('equipment_brand').value=$('manual_brand').value;$('equipment_model').value=$('manual_model').value}));function selectAsset(a){if(!a)return;$('asset_id').value=a.id;$('asset_type').value=a.asset_type||a.asset_category||a.name||'GENERAL';$('equipment_brand').value=a.manufacturer||'';$('equipment_model').value=a.model_no||'';$('ac-code').textContent=a.asset_code||'—';$('ac-name').textContent=a.name||'—';$('ac-type').textContent=a.asset_type||a.asset_category||'—';$('ac-brand').textContent=a.manufacturer||'—';$('ac-model').textContent=a.model_no||'—';$('ac-serial').textContent=a.serial_no||a.manufacturer_asset_number||'—';$('ac-site').textContent=a.site_name||'—';$('ac-status').textContent=a.operational_status||'—';$('asset-card').classList.add('show')}
$('maintenance-form').addEventListener('submit',e=>{if(!customer){e.preventDefault();alert('يرجى إدخال رقم العميل وجلب بياناته أولًا.');return}if(!$('contract_no').value){e.preventDefault();alert('يرجى اختيار العقد.');return}if(!$('site_id').value){e.preventDefault();alert('يرجى اختيار الموقع.');return}const manual=$('manual-fields').classList.contains('show');if(!manual&&!$('asset_id').value){e.preventDefault();alert('يرجى اختيار المعدة أو البحث عنها.');return}if(manual&&!$('manual_name').value.trim()){e.preventDefault();alert('يرجى إدخال بيانات المعدة غير التعاقدية.')}});function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}})();
</script>
</body></html>
